/// The zones cities set for shared scooters, as src/lib/ruleZones.ts reads data/city-zones.json: where to
/// park, where not to, where to ride slowly and where not to ride, each one ring.
extension CityRuleZone {
    static let cityZones: [CityRuleZone] =
        zones(
            authority: "32 CFR 553.33(c)(8), outline © OpenStreetMap", timeZone: "America/New_York",
            source: URL(string: "https://www.ecfr.gov/current/title-32/section-553.33")!,
            ids: arlingtoncemeteryZoneIds, kinds: arlingtoncemeteryZoneKinds, rings: arlingtoncemeteryZoneRings
        ) +
        zones(
            authority: "Bergen kommune", timeZone: "Europe/Oslo",
            source: URL(string: "https://www.bergen.kommune.no/innbyggerhjelpen/vann-vei-og-trafikk/vei-transport-og-parkering/sykkel/elsparkesykler-i-bergen")!,
            ids: bergenZoneIds, kinds: bergenZoneKinds, rings: bergenZoneRings
        ) +
        zones(
            authority: "City of Boise", timeZone: "America/Boise",
            source: URL(string: "https://www.cityofboise.org/departments/finance/how-to-use-e-scooters-and-e-bikes/")!,
            ids: boiseZoneIds, kinds: boiseZoneKinds, rings: boiseZoneRings
        ) +
        zones(
            authority: "Lime", timeZone: "America/Denver",
            source: URL(string: "https://bouldercolorado.gov/services/shared-e-scooters-and-e-bikes")!,
            ids: boulderZoneIds, kinds: boulderZoneKinds, rings: boulderZoneRings
        ) +
        zones(
            authority: "Norrköpings kommun", timeZone: "Europe/Stockholm",
            source: URL(string: "https://norrkoping.se/boende-trafik-och-miljo/resa-och-parkera/elsparkcyklar")!,
            ids: norrkopingZoneIds, kinds: norrkopingZoneKinds, rings: norrkopingZoneRings
        ) +
        zones(
            authority: "Porto", timeZone: "Europe/Lisbon",
            source: URL(string: "https://echoboomer.pt/policia-municipal-porto-multou-trotinetes-mal-estacionadas")!,
            ids: portoZoneIds, kinds: portoZoneKinds, rings: portoZoneRings
        ) +
        zones(
            authority: "Västerås stad", timeZone: "Europe/Stockholm",
            source: URL(string: "https://www.vasteras.se/trafik-och-gator/hallbara-resor/res-med-elsparkcykel.html")!,
            ids: vasterasZoneIds, kinds: vasterasZoneKinds, rings: vasterasZoneRings
        )

    /// Each zone of a city, its ring as latitude, longitude, latitude, longitude…
    private static func zones(
        authority: String, timeZone: String, source: URL, ids: [String], kinds: [ScooterZoneKind], rings: [[Double]]
    ) -> [CityRuleZone] {
        zip(ids, zip(kinds, rings)).map { id, zone in
            CityRuleZone(
                id: id, authority: authority, timeZone: timeZone, kind: zone.0, source: source,
                ring: stride(from: 0, to: zone.1.count, by: 2).map { GeoPoint(latitude: zone.1[$0], longitude: zone.1[$0 + 1]) }
            )
        }
    }

